
'use strict';

const ICONS={"hat": "/static/build/media/6d225bb7bdfc.png", "shield": "/static/build/media/c293a01bae8e.png", "sword": "/static/build/media/11eaffec651c.png", "charter": "/static/build/media/b9b8da084909.png"};
let modalView='full';
function iconKey(v){
  if(!v) return 'charter';
  if(['👑','hat','vua','hoàng'].some(k=>String(v).toLowerCase().includes(k))) return 'hat';
  if(['⚔','sword','tướng','chiến','quân','xâm lược'].some(k=>String(v).toLowerCase().includes(k))) return 'sword';
  if(['🛡','shield','phòng thủ','kháng chiến'].some(k=>String(v).toLowerCase().includes(k))) return 'shield';
  if(['📜','charter','văn','sắc phong','kiến lập'].some(k=>String(v).toLowerCase().includes(k))) return 'charter';
  return 'charter';
}
function iconHtml(v, cls='icon-img', alt=''){ const k=iconKey(v); return `<img class="${cls}" src="${ICONS[k]}" alt="${alt||k}">`; }
function avatarHtml(v, alt=''){ return iconHtml(v,'',alt); }
function setModalView(mode){ modalView=mode; const ov=document.getElementById('overlay'); ov.classList.remove('view-mid','view-wide','view-full'); ov.classList.add('view-'+mode); ['mid','wide','full'].forEach(m=>{ const b=document.getElementById('size-'+m); if(b) b.classList.toggle('active',m===mode); }); }
function roleIcon(role=''){ role=String(role).toLowerCase(); if(role.includes('hoàng')||role.includes('vua')) return 'hat'; if(role.includes('tướng')||role.includes('tiết chế')) return 'sword'; if(role.includes('phòng')||role.includes('kháng')) return 'shield'; return 'charter'; }


