function setCompare(mode){currentCompare=mode; const el=document.getElementById('atlas');el.classList.remove('mode-cn','mode-west','mode-all');el.classList.add('mode-'+mode);document.querySelectorAll('.compare-btn').forEach(b=>{b.classList.toggle('active',b.dataset.mode===mode);b.setAttribute('aria-pressed',String(b.dataset.mode===mode))});}
