const battles={
battle1858:{name:'Liên quân Pháp – Tây Ban Nha đánh Đà Nẵng (1858)',desc:'Năm 1858, liên quân Pháp – Tây Ban Nha tấn công Đà Nẵng. Cuộc viễn chinh mở đầu một quá trình chinh phục và thiết lập sự thống trị thuộc địa của Pháp tại Việt Nam. Bối cảnh gồm tham vọng địa chính trị và thương mại, can thiệp với lý do tôn giáo, cùng ưu thế về hải quân và hỏa lực.',links:['Triều Nguyễn','Pháp dưới thời Napoleon III','Tây Ban Nha','Đà Nẵng']},
battle938:{name:'Chiến thắng Bạch Đằng 938',year:938,desc:'Ngô Quyền đánh bại quân Nam Hán, đánh dấu bước ngoặt trong tiến trình giành độc lập.',links:['Ngô Quyền','Quân Nam Hán']},battle981:{name:'Chiến tranh Tống – Việt 981',year:981,desc:'Đại Cồ Việt dưới thời Lê Hoàn đẩy lùi cuộc tiến công của nhà Tống.',links:['Lê Hoàn','Nhà Tống']},battle1075:{name:'Chiến tranh Tống – Đại Việt 1075–1077',year:1075,desc:'Cuộc chiến thời nhà Lý với Bắc Tống, gắn với vai trò của Lý Thường Kiệt.',links:['Lý Thường Kiệt','Tống Thần Tông']},battle1258:{name:'Kháng chiến chống Mông Cổ 1258',year:1258,desc:'Cuộc kháng chiến lần thứ nhất chống quân Mông Cổ của Đại Việt dưới thời Trần.',links:['Trần Thái Tông','Quân Mông Cổ']},battle1285:{name:'Kháng chiến chống Nguyên 1285',year:1285,desc:'Đại Việt chống cuộc xâm lược lớn của nhà Nguyên; gắn với Trần Nhân Tông và Trần Hưng Đạo.',links:['Trần Hưng Đạo','Hốt Tất Liệt','Thoát Hoan']},battle1288:{name:'Chiến thắng Bạch Đằng 1288',year:1288,desc:'Một trận đánh quyết định trong cuộc kháng chiến chống Nguyên lần thứ ba của Đại Việt.',links:['Trần Hưng Đạo','Trần Nhân Tông','Hốt Tất Liệt']},battle1789:{name:'Ngọc Hồi – Đống Đa 1789',year:1789,desc:'Quân Tây Sơn dưới sự chỉ huy của Quang Trung đánh bại lực lượng quân Thanh tiến vào Đại Việt.',links:['Quang Trung','Càn Long','Tôn Sĩ Nghị']}};
Object.assign(battles,{
war1946:{name:'Toàn quốc kháng chiến (1946)',year:1946,desc:'Ngày 19/12/1946, cuộc kháng chiến toàn quốc chống thực dân Pháp bùng nổ. Những năm tiếp theo diễn ra chiến tranh Đông Dương lần thứ nhất.',links:['Chính phủ Việt Nam Dân chủ Cộng hòa','Pháp','Hà Nội']},
war1954:{name:'Điện Biên Phủ và Hiệp định Genève (1954)',year:1954,desc:'Chiến thắng Điện Biên Phủ ngày 7/5/1954, sau đó là các văn kiện Genève về Đông Dương. Việt Nam tạm thời có hai vùng tập kết quân sự, đường phân giới gần vĩ tuyến 17; không đồng nghĩa với biên giới quốc gia vĩnh viễn.',links:['Điện Biên Phủ','Võ Nguyên Giáp','Hiệp định Genève']},
war1960:{name:'Mặt trận Dân tộc Giải phóng miền Nam (1960)',year:1960,desc:'Ngày 20/12/1960, Mặt trận Dân tộc Giải phóng miền Nam Việt Nam được thành lập trong bối cảnh xung đột chính trị và vũ trang ở miền Nam.',links:['Miền Nam Việt Nam','Chiến tranh Lạnh']},
war1964:{name:'Sự kiện Vịnh Bắc Bộ (1964)',year:1964,desc:'Các sự kiện đầu tháng 8/1964 và Nghị quyết Vịnh Bắc Bộ là bước ngoặt trong quá trình Mỹ mở rộng chiến tranh. Những tình tiết của sự kiện ngày 4/8 đã được xem xét lại qua tài liệu giải mật.',links:['Vịnh Bắc Bộ','Hoa Kỳ','Việt Nam Dân chủ Cộng hòa']},
war1965:{name:'Mỹ đưa quân chiến đấu vào Việt Nam (1965)',year:1965,desc:'Ngày 8/3/1965, lực lượng thủy quân lục chiến Mỹ tới Đà Nẵng; can dự quân sự trực tiếp của Mỹ tăng nhanh trong những năm tiếp theo.',links:['Đà Nẵng','Hoa Kỳ','Việt Nam Cộng hòa']},
war1968:{name:'Tết Mậu Thân 1968',year:1968,desc:'Cuộc Tổng tiến công và nổi dậy Tết Mậu Thân diễn ra trên nhiều đô thị và địa bàn miền Nam; dù thiệt hại quân sự lớn, sự kiện tạo tác động mạnh về chính trị và dư luận tại Hoa Kỳ.',links:['Huế','Sài Gòn','Hoa Kỳ']},
war1972:{name:'Chiến sự 1972',year:1972,desc:'Năm 1972 có những chiến dịch quy mô lớn và cuộc tập kích bằng máy bay chiến lược vào Hà Nội, Hải Phòng cuối tháng 12, trong khi các cuộc đàm phán tiếp tục.',links:['Quảng Trị','Hà Nội','Hải Phòng']},
war1973:{name:'Hiệp định Paris năm 1973',year:1973,desc:'Hiệp định về chấm dứt chiến tranh, lập lại hòa bình ở Việt Nam được ký ngày 27/1/1973. Quân Mỹ rút đi, nhưng chiến sự giữa các lực lượng Việt Nam chưa kết thúc.',links:['Paris','Hoa Kỳ','Việt Nam Dân chủ Cộng hòa','Việt Nam Cộng hòa']},
war1975:{name:'Chiến dịch mùa Xuân 1975',year:1975,desc:'Các chiến dịch quân sự đầu năm 1975 dẫn tới ngày 30/4/1975, khi chính quyền Việt Nam Cộng hòa đầu hàng và chiến tranh kết thúc. Nước Việt Nam thống nhất về mặt nhà nước năm 1976.',links:['Tây Nguyên','Huế – Đà Nẵng','Sài Gòn']},
war1977:{name:'Xung đột biên giới Việt Nam – Campuchia (1977)',year:1977,desc:'Xung đột biên giới gia tăng, nhiều cuộc tấn công của lực lượng Khmer Đỏ vào lãnh thổ Việt Nam gây thương vong cho binh sĩ và dân thường. Quan hệ hai nước nhanh chóng leo thang thành chiến tranh.',links:['Biên giới Tây Nam','Campuchia Dân chủ','Khmer Đỏ']},
war1978:{name:'Chiến tranh biên giới Tây Nam (1978)',year:1978,desc:'Giao tranh Việt Nam – Campuchia tiếp diễn. Cuối tháng 12/1978, quân đội Việt Nam cùng lực lượng Campuchia chống Khmer Đỏ mở chiến dịch tiến vào Campuchia. Cần tìm hiểu cả bối cảnh xung đột biên giới, tội ác Khmer Đỏ và phản ứng quốc tế.',links:['Biên giới Tây Nam','Khmer Đỏ','Campuchia']},
war1979cam:{name:'Campuchia năm 1979',year:1979,desc:'Ngày 7/1/1979, Phnom Penh được các lực lượng Việt Nam và Campuchia chống Khmer Đỏ kiểm soát, chấm dứt chính quyền Khmer Đỏ tại thủ đô. Quân đội Việt Nam tiếp tục hiện diện ở Campuchia trong các năm sau.',links:['Phnom Penh','Campuchia','Việt Nam']},
war1979:{name:'Chiến tranh biên giới Việt – Trung (1979)',year:1979,desc:'Ngày 17/2/1979, quân Trung Quốc tấn công qua nhiều hướng dọc biên giới phía Bắc Việt Nam. Trung Quốc công bố rút quân từ đầu tháng 3, hoàn thành rút quân vào giữa tháng 3. Xung đột biên giới còn kéo dài sau năm 1979.',links:['Lạng Sơn','Cao Bằng','Lào Cai','Việt Nam','Trung Quốc']}
});
