function normAI(t){return String(t).toLocaleLowerCase('vi').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/đ/g,'d');}
function toggleHistoryAI(open){const p=document.getElementById('historyAI');p.classList.toggle('open',open);document.getElementById('aiOpen').style.display=open?'none':'flex';if(open)document.getElementById('aiQuestion').focus();}
function aiBubble(text,mine=false){const target=document.getElementById('aiMessages');const d=document.createElement('div');d.className='ai-bubble'+(mine?' mine':'');const p=document.createElement('p');p.textContent=text;d.append(p);target.append(d);target.scrollTop=target.scrollHeight;return d;}
function aiLink(parent,label,func){const b=document.createElement('button');b.textContent=label;b.addEventListener('click',func);parent.append(b);}
function askSuggested(q){document.getElementById('aiQuestion').value=q;document.querySelector('.ai-form').requestSubmit();}
function openFromAI(id,y){toggleHistoryAI(false);if(y)goYear(y);if(id)openItem(id);}
async function searchWikipedia(q,bubble){if(!navigator.onLine){const p=document.createElement('p');p.textContent='Thiết bị đang ngoại tuyến. Khi có mạng, có thể tìm nguồn tham khảo trực tuyến.';bubble.append(p);return;}const p=document.createElement('p');p.textContent='Đang kiểm tra nguồn Wikipedia tiếng Việt...';bubble.append(p);try{const endpoint='https://vi.wikipedia.org/w/api.php?action=query&generator=search&gsrsearch='+encodeURIComponent(q)+'&gsrlimit=3&prop=info&inprop=url&format=json&origin=*';const control=new AbortController();const abort=setTimeout(()=>control.abort(),6500);let res;try{res=await fetch(endpoint,{signal:control.signal});}finally{clearTimeout(abort);}if(!res.ok)throw Error('HTTP '+res.status);const data=await res.json();const pages=Object.values(data.query?.pages||{}).slice(0,3);p.textContent=pages.length?'Nguồn đọc thêm (cần kiểm chứng):':'Chưa có kết quả tìm kiếm từ Wikipedia.';for(const page of pages){const link=document.createElement('a');link.href=page.fullurl||'https://vi.wikipedia.org/?curid='+page.pageid;link.target='_blank';link.rel='noopener noreferrer';link.textContent=page.title+' ↗';bubble.append(link);}}catch(e){p.textContent='Không tải được nguồn trực tuyến ở trình duyệt này. Anh có thể mở tìm kiếm ngoài.';}
const link=document.createElement('a');link.href='https://www.google.com/search?q='+encodeURIComponent(q+' lịch sử');link.target='_blank';link.rel='noopener noreferrer';link.textContent='Tìm thêm trên web ↗';bubble.append(link);}
function sendHistoryQuestion(event){event.preventDefault();const input=document.getElementById('aiQuestion');const q=input.value.trim();if(!q)return;aiBubble(q,true);input.value='';const normalized=normAI(q);const scored=aiIndex.map(x=>({x,score:x.q.reduce((best,k)=>Math.max(best,normalized.includes(normAI(k))?normAI(k).length:0),0)})).sort((a,b)=>b.score-a.score);const hit=scored[0].score>0?scored[0].x:null;const bubble=aiBubble(hit?hit.text:'Chưa có dữ liệu được biên tập cho câu hỏi này trong bản offline. Anh có thể tìm nguồn trực tuyến và đối chiếu trước khi đưa vào học liệu.');if(hit){aiLink(bubble,'Mở '+hit.name+' ↗',()=>openFromAI(hit.id,hit.year));aiLink(bubble,'Đến năm '+hit.year,()=>{toggleHistoryAI(false);goYear(hit.year);});}aiLink(bubble,'Tìm nguồn trên web',()=>searchWikipedia(q,bubble));}


