function showSection(section){const isHcm=section==='hcm'; document.getElementById('mainHistory').hidden=isHcm; document.getElementById('hcmHistory').hidden=!isHcm;document.getElementById('navMain').classList.toggle('active',!isHcm);document.getElementById('navHCM').classList.toggle('active',isHcm);document.getElementById('mobileMain').classList.toggle('active',!isHcm);document.getElementById('mobileHCM').classList.toggle('active',isHcm);document.querySelector('.crumb').innerHTML=isHcm?'VIỆT SỬ <b>/</b> Chủ tịch Hồ Chí Minh':'VIỆT SỬ <b>/</b> Timeline Việt Nam – Trung Quốc – Phương Tây';window.scrollTo({top:0,behavior:'smooth'});}
function hcmX(y){return 110+(y-1890)/(2026-1890)*4160}

function mainEraName(id, year, fallback){
 const candidates=eras.filter(e=>e.y<=year).flatMap(e=>e.v||[]).filter(x=>x[2]===id);
 return candidates.length?candidates[candidates.length-1][0]:fallback;
}
// Government bands are projections of governments already represented by IDs and names in `eras`.
// Date boundaries are period metadata, while labels resolve from the shared main timeline.
const hcmGovernmentPeriods=[
 {start:1890,end:1945,id:'nguyenvn',fallback:'Nhà Nguyễn',label:'Triều Nguyễn',lane:0},
 {start:1890,end:1945,id:'nguyenvn',fallback:'Đông Dương thuộc Pháp',label:'Chế độ thuộc địa Pháp',lane:1,cls:'colonial'},
 {start:1945,end:1976,id:'vnmodern',fallback:'Việt Nam Dân chủ Cộng hòa',label:'Việt Nam Dân chủ Cộng hòa',lane:0},
 {start:1949,end:1955,id:'south',fallback:'Quốc gia Việt Nam',label:'Quốc gia Việt Nam',lane:1,cls:'south'},
 {start:1955,end:1975,id:'south',fallback:'Việt Nam Cộng hòa',label:'Việt Nam Cộng hòa',lane:1,cls:'south'},
 {start:1976,end:2026,id:'vnmodern',fallback:'CHXHCN Việt Nam',label:'CHXHCN Việt Nam',lane:0,cls:'current'}
];
function hcmGovernmentName(g){
 // Specific 1945 / 1949 / 1955 boundaries are editorial period labels.
 // The matching records and government IDs also exist in the main historical timeline.
 const ref=eras.find(e=>e.y>=g.start&&e.y<=g.end&&e.v.some(x=>x[2]===g.id&&x[0]===g.label));
 return ref?ref.v.find(x=>x[2]===g.id&&x[0]===g.label)[0]:g.label;
}
function hcmContextAt(year){
 return hcmGovernmentPeriods.filter(g=>year>=g.start&&year<=g.end).map(g=>hcmGovernmentName(g)).join(' · ');
}
function hcmChapterAt(year){return hcmChapters.find(c=>year>=c.start && (year<c.end||year===2026))||hcmChapters[hcmChapters.length-1]}
function buildHCM(){
 const wrap=document.getElementById('hcmHistory');
 const chapters=hcmChapters.map((c,i)=>`<button class="hcm-chapter" style="left:${hcmX(c.start)}px;width:${hcmX(c.end)-hcmX(c.start)-4}px" onclick="hcmGo(${c.start})"><strong>${i+1}. ${safe(c.title)}</strong><span>${c.short}</span></button>`).join('');
 const gov=hcmGovernmentPeriods.map(g=>{const x=hcmX(g.start),w=Math.max(25,hcmX(g.end)-x-4);return `<button class="hcm-government ${g.cls||''}" style="left:${x}px;top:${477+g.lane*70}px;width:${w}px;height:56px" onclick="openGovernment('${g.id}',${g.start},'${g.label}')"><div><b>${safe(hcmGovernmentName(g))}</b><span>${g.start}–${g.end===2026?'nay':g.end}</span></div></button>`}).join('');
 const cards=hcmEvents.map((e,i)=>`<button class="hcm-event" style="left:${hcmX(e.year)}px;top:${160+(i%3)*69}px" onclick="openHCM(${e.year})"><small>${safe(e.date)}</small><b>${safe(e.title)}</b><span>Đọc câu chuyện ↗</span></button>`).join('');
 const mobile=hcmChapters.map((c,i)=>`<div class="hcm-mobile-chapter">${i+1}. ${safe(c.title)}<small>${c.short}</small></div>${hcmEvents.filter((e,j)=>e.year>=c.start&&(e.year<c.end||(i===6&&e.year===2026))).map(e=>`<button class="hcm-mobile-card" onclick="openHCM(${e.year})"><span class="date">${safe(e.date)}</span><b>${safe(e.title)}</b><div class="hcm-mobile-context">Cùng thời: ${safe(hcmContextAt(e.year))}</div><small>Xem bài viết ↗</small></button>`).join('')}`).join('');
 wrap.innerHTML=`<div class="hcm-page"><div class="hcm-intro"><span class="eyebrow">DÒNG THỜI GIAN NHÂN VẬT · 7 CHẶNG THEO TƯ LIỆU ANH GỬI</span><h2>CHỦ TỊCH HỒ CHÍ MINH</h2><div class="hcm-toolbar"><button class="toolbtn" onclick="hcmGo(1911)">1911 · Ra đi</button><button class="toolbtn" onclick="hcmGo(1941)">1941 · Trở về</button><button class="toolbtn" onclick="hcmGo(1945)">1945 · Độc lập</button><button class="toolbtn" onclick="hcmGo(1969)">1969 · Di sản</button><button class="toolbtn" onclick="hcmGo(2026)">Đến hiện tại</button></div></div><div class="hcm-board v18"><div class="hcm-board-header"><div><h3>Cuộc đời Hồ Chí Minh và bối cảnh lịch sử song hành</h3><small>Thanh năm chung · kéo ngang để khám phá · chọn thẻ mở Popup</small></div><div class="hcm-controls"><button onclick="hcmPan(-520)" aria-label="Về trước">←</button><button onclick="hcmZoom(-1)" aria-label="Thu nhỏ">−</button><strong id="hcmCurrent">1890</strong><button onclick="hcmZoom(1)" aria-label="Phóng to">+</button><button onclick="hcmPan(520)" aria-label="Tiếp theo">→</button></div></div><div class="hcm-scroll" id="hcmScroll"><div class="hcm-track" id="hcmTrack"><div class="hcm-life-label">CUỘC ĐỜI VÀ DI SẢN</div><div class="hcm-gov-label">CHÍNH QUYỀN / THỜI KỲ CÙNG THỜI</div><div class="hcm-axis"></div>${Array.from({length:14},(_,i)=>1890+i*10).concat([2026]).map(y=>`<div class="hcm-tick" style="left:${hcmX(y)}px">${y}</div>`).join('')}${chapters}${cards}${gov}<p class="hcm-gov-note">Dải dưới liên kết tới dữ liệu các chính quyền đã có ở timeline chính; những giai đoạn chồng lấn được thể hiện thành nhiều hàng.</p></div></div><div class="hcm-year-range"><b>1890</b><input id="hcmSlider" type="range" min="1890" max="2026" step="1" value="1890" oninput="hcmGo(Number(this.value))"><b>2026</b></div></div><div class="hcm-mobile">${mobile}</div><p class="hcm-source v23-hcm-note">Nội dung đang ở dạng thử nghiệm · V3.7</p></div>`;
}
function openGovernment(id,year,label){if(details[id]){openItem(id)}else{openItem('gov:'+id+':'+year)}}
function hcmPan(delta){document.getElementById('hcmScroll')?.scrollBy({left:delta,behavior:'smooth'})}
let hcmScale=1;
function hcmZoom(delta){hcmScale=Math.min(1.6,Math.max(.7,hcmScale+delta*.15));const track=document.getElementById('hcmTrack');track.style.zoom=hcmScale;}
function hcmGo(year){year=Math.min(2026,Math.max(1890,year));const el=document.getElementById('hcmScroll');if(el)el.scrollTo({left:hcmX(year)*hcmScale-el.clientWidth/2,behavior:'smooth'});const t=document.getElementById('hcmCurrent');if(t)t.textContent=year;const r=document.getElementById('hcmSlider');if(r)r.value=year}
function openHCM(year){openItem('hcm:'+year)}
function hcmBody(){const year=Number(active.split(':')[1]);const e=hcmEvents.find(x=>x.year===year);if(!e)return '<p>Đang cập nhật tư liệu.</p>';return `<div class="panel"><span class="chip">CHỦ TỊCH HỒ CHÍ MINH · ${e.date}</span><h3>${e.title}</h3><p>${e.detail}</p></div><div class="panel"><h3>Bối cảnh chính quyền cùng thời</h3><p>${safe(hcmContextAt(year))}</p></div><div class="panel"><h3>Thư viện tư liệu</h3><p>Bản V3.0 đang thử bố cục. Những phiên bản tiếp theo sẽ bổ sung ảnh tư liệu, đoạn phim, sơ đồ liên kết và nguồn chú giải cho sự kiện này.</p></div><div class="actions"><button class="secondary" onclick="closeModal();showSection('hcm');hcmGo(${e.year})">↩ Trở về dòng thời gian</button></div>${v2HcmExtra(year)}`}


