function v2ShowHotspot(id,idx){const scene=V2_EXPERIENCES.find(x=>x.id===id);const el=document.getElementById('v2HotspotInfo');if(scene&&el&&scene.hotspots[idx])el.textContent=scene.hotspots[idx][1];}
function v2Return(id,year){closeModal();if(id==='lang-sen'){showSection('hcm');hcmGo(1890)}else{showSection('main');goYear(year)}}
async function v2LoadLinks(id){
 if(!['http:','https:'].includes(location.protocol)||!document.getElementById('modalbody'))return;
 try{
  const response=await fetch('/api/articles?status=published&entity_id='+encodeURIComponent(id));
  if(!response.ok)return; const articles=await response.json();
  if(!Array.isArray(articles)||!articles.length||active!==id)return;
  document.getElementById('v2-server-links')?.remove();
  const pane=document.createElement('div');pane.className='panel';pane.id='v2-server-links';
  const h=document.createElement('h3');h.textContent='Bài viết chuyên sâu đã xuất bản';pane.append(h);
  for(const a of articles){const p=document.createElement('p');const link=document.createElement('a');link.textContent=a.title+' ↗';link.href='/bai-viet/'+encodeURIComponent(a.slug);link.target='_blank';link.rel='noopener';link.style.color='#e9c485';p.append(link);pane.append(p)}
  document.getElementById('modalbody').append(pane);
 }catch(e){/* Offline HTML does not have a backend. */}
}
function v2SceneHtml(scene){return `<div class="v2-space"><span class="chip">KHÔNG GIAN TƯƠNG TÁC · BẢN THỬ</span><h3>${safe(scene.title)} · ${safe(scene.period)}</h3><p>${safe(scene.description)}</p><div class="v2-hotspots">${scene.hotspots.map((p,i)=>`<button type="button" onclick="v2ShowHotspot('${scene.id}',${i})">📍 ${safe(p[0])}</button>`).join('')}</div><div class="v2-hotspot-text" id="v2HotspotInfo">Chọn một điểm để xem mô tả. Đây là bản mô phỏng giao diện, chưa phải môi trường game 3D.</div><div class="actions" style="margin-top:15px"><button class="secondary" onclick="v2Return('${scene.id}',${scene.year})">↩ Trở về dòng thời gian</button></div></div>`}
function v2ExperienceList(){return `<section class="v2-experiences"><h2>Không gian lịch sử tương tác</h2><p>Định hướng tích hợp tour 3D, sa bàn chiến trận và tương tác NPC trong tương lai. Hiện tại đây là sơ đồ các điểm dừng mẫu và yêu cầu nội dung cần thẩm định.</p><div class="v2-grid">${V2_EXPERIENCES.map(s=>`<button class="v2-scene" onclick="openItem('scene:${s.id}')"><small>${safe(s.kind)} · ${safe(s.period)}</small><b>${safe(s.title)}</b><span>${safe(s.description).slice(0,118)}…</span></button>`).join('')}</div></section>`}
function v2DynastyExtra(id){const d=V2_CONTENT[id];if(!d)return '';const articles=d.sections.map((v,i)=>`<div class="panel"><h3>${safe(v[0])}</h3><p>${safe(v[1])}</p></div>`).join('');return `<div class="panel"><h3>Nội dung mở rộng V2.0</h3><p>Hồ sơ sơ bộ để thử bố cục; các thông tin chuyên sâu cần đối chiếu nguồn trước khi công bố.</p><p>${d.tags.map(t=>`<span class="chip">${safe(t)}</span>`).join(' ')}</p></div>${articles}<div class="panel"><h3>Đọc bài viết liên quan</h3><p>Khi chạy backend, bài viết có thể được tạo với SEO, nguồn tư liệu, nhân vật liên quan và liên kết về đúng mốc timeline.</p><button class="secondary" onclick="alert('Tính năng biên tập bài viết có trong bộ mã backend V2.0. Chạy server rồi truy cập /admin để biên tập nội dung.')">Mở quy trình biên tập ↗</button></div>`}
function v2HcmExtra(year){const start=Object.keys(V2_HCM_CHAPTER_ARTICLES).map(Number).filter(x=>x<=year).sort((a,b)=>b-a)[0]||1890;const arts=V2_HCM_CHAPTER_ARTICLES[start]||[];return `<div class="panel"><h3>Đề cương bài viết cùng chặng</h3><p>Nội dung mẫu theo mục lục giai đoạn, chưa thay cho bài thẩm định chính thức.</p>${arts.map(a=>`<div class="v2-related-article"><div><b>${safe(a[0])}</b><br><small>${safe(a[1])} · ${safe(a[2])}</small></div><button onclick="alert('Đây là đề cương. Bài viết chi tiết sẽ được tạo và kiểm duyệt trong CMS V2.0.')">Xem đề cương</button></div>`).join('')}<p><a style="color:#f1d7a0" href="${V2_SOURCES.hcm}" target="_blank" rel="noopener">Nguồn tư liệu tiểu sử Bảo tàng Hồ Chí Minh ↗</a></p></div>${year<=1901?v2SceneHtml(V2_EXPERIENCES[0]):''}`}

